{
  "name": "txpwr_send_state",
  "confidence": "medium",
  "docstring": "Builds transmit-power/RF state notification messages from the active TX-power context and sends them through the HCI command path.",
  "subsystem": "phy",
  "var_renames": {
    "v0": "txpwr_ctx_table_base",
    "v1": "rf_config_ptr",
    "v2": "txpwr_ctx_idx",
    "v6": "txpwr_ctx",
    "v7": "txpwr_state_msg",
    "v14": "txpwr_off_state_msg"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "txpwr_ctx flags word; bit 0x20 is set when the calibration/txpower state flag is active"
    },
    {
      "offset": 51,
      "meaning": "current txpwr/rf context or path index"
    },
    {
      "offset": 100,
      "meaning": "txpwr_ctx 32-bit state field copied into the first report message"
    },
    {
      "offset": 104,
      "meaning": "txpwr_ctx 16-bit state field copied into the first report message"
    },
    {
      "offset": 107,
      "meaning": "txpwr_ctx byte state value copied into notification messages"
    },
    {
      "offset": 1224,
      "meaning": "txpwr_ctx enable/calibration-state byte; nonzero selects the 'active' reporting path"
    },
    {
      "offset": 16,
      "meaning": "rf_config byte field copied into the second report message"
    },
    {
      "offset": 40,
      "meaning": "rf_config 16-bit field copied into the third report message"
    }
  ]
}
